// Shared event rules. Projects remain plain data: no generated JavaScript or eval.
export const triggers={start:'Game starts',timer:'Timer finishes',key:'Key is pressed',mouse:'Mouse is clicked',objectclick:'This object is clicked',touch:'Player touches an object',variable:'Counter matches'};
export const actionTypes={addvariable:'Add to counter',setvariable:'Set counter',show:'Show object',hide:'Hide object',toggle:'Show / hide object',move:'Move object',sound:'Play sound or music',stopsound:'Stop sound or music',setgravity:'Change gravity',jump:'Jump',slide:'Slide',tag:'Tag nearby player',checkpoint:'Save checkpoint',finish:'Finish level',group:'Run saved actions'};
export const comparisons={eq:'equals',ne:'does not equal',atleast:'is at least',above:'is above',below:'is below',atmost:'is at most'};
const finite=(v,max=1e6)=>Number.isFinite(v)&&Math.abs(v)<=max;
const text=(v,max=80)=>typeof v==='string'&&v.length<=max;
export function compare(value,op,threshold){switch(op){case'eq':return value===threshold;case'ne':return value!==threshold;case'above':return value>threshold;case'below':return value<threshold;case'atmost':return value<=threshold;default:return value>=threshold}}
export function counter(state,name){return name==='Score'?Number(state.score)||0:name==='Health'?Number(state.health)||0:Number(state.variables?.[name])||0}
export function guardsPass(state,rule){const tests=rule.guards||[];if(!tests.length)return true;const test=g=>compare(counter(state,g.variable),g.op,g.value);return rule.guardMode==='any'?tests.some(test):tests.every(test)}
export function validateRules(project,{allowMissingReferences=false}={}){const rules=project.rules||[],groups=project.actionGroups||[];if(!Array.isArray(rules)||rules.length>200||!Array.isArray(groups)||groups.length>50)throw Error('Keep the project to 200 events and 50 saved action groups.');const objectIds=new Set((project.objects||[]).map(o=>o.id)),soundIds=new Set((project.sounds||[]).map(s=>s.id)),groupIds=new Set(groups.map(g=>g?.id));if(groupIds.size!==groups.length)throw Error('Saved action groups need unique IDs.');const ids=new Set();function actionsValid(actions){if(!Array.isArray(actions)||!actions.length||actions.length>30)throw Error('An event needs 1–30 actions.');for(const a of actions){if(!a||!Object.hasOwn(actionTypes,a.type))throw Error('Choose a supported action.');if(['addvariable','setvariable'].includes(a.type)&&(!text(a.variable,40)||!a.variable.trim()||!finite(a.value)))throw Error('Choose a counter and a valid amount.');if(['show','hide','toggle','move'].includes(a.type)&&(!text(a.targetId)||!a.targetId||!allowMissingReferences&&!objectIds.has(a.targetId)))throw Error('Choose an existing object for this action.');if(a.type==='move'&&(!['x','y','z'].includes(a.axis)||project.dimension!=='3d'&&a.axis==='z'||!finite(a.value)||a.duration!==undefined&&(!finite(a.duration,3600)||a.duration<0)))throw Error('Check the movement distance and duration.');if(a.type==='sound'&&((!text(a.soundId)||!a.soundId||!allowMissingReferences&&!soundIds.has(a.soundId))||a.loop!==undefined&&typeof a.loop!=='boolean'))throw Error('Choose a saved sound. Add one in Tools → Sounds & effects first.');if(a.type==='stopsound'&&a.soundId&&(!text(a.soundId)||!a.soundId||!allowMissingReferences&&!soundIds.has(a.soundId)))throw Error('Choose a saved sound or stop all sounds.');if(a.type==='group'&&(!text(a.groupId)||!a.groupId||!allowMissingReferences&&!groupIds.has(a.groupId)))throw Error('Choose an existing saved action group.');if(a.type==='setgravity'&&(!finite(a.value,10)||a.value<0))throw Error('Gravity must be between 0 and 10.');if(project.dimension!=='3d'&&['slide','tag'].includes(a.type))throw Error('Slide and tag actions currently need a 3D project.')}}
 for(const g of groups){if(!g||!text(g.id)||!g.id||!text(g.name,60)||!g.name.trim())throw Error('Give each saved action group a name.');actionsValid(g.actions)}
 for(const r of rules){if(!r||!text(r.id)||!r.id||ids.has(r.id)||r.enabled!==undefined&&typeof r.enabled!=='boolean'||!text(r.name||'',80)||!r.when||!Object.hasOwn(triggers,r.when.type))throw Error('Invalid event rule.');ids.add(r.id);const w=r.when;if(['objectclick','touch'].includes(w.type)&&(!text(w.objectId)||!w.objectId||!allowMissingReferences&&!objectIds.has(w.objectId)))throw Error('Choose an existing object for this event.');if(w.type==='timer'&&(!finite(w.seconds,3600)||w.seconds<.05||typeof w.repeat!=='boolean'))throw Error('Timers need an interval from 0.05 to 3600 seconds.');if(w.type==='key'&&(!text(w.code,32)||!/^[A-Za-z0-9]{1,32}$/.test(w.code)))throw Error('Choose a keyboard key.');if(w.type==='mouse'&&![0,1,2].includes(w.button))throw Error('Choose a mouse button.');if(w.type==='variable'&&(!text(w.variable,40)||!w.variable||!Object.hasOwn(comparisons,w.op)||!finite(w.value)))throw Error('Check the counter condition.');if(!Array.isArray(r.guards||[])||(r.guards||[]).length>8||(r.guards||[]).some(g=>!g||!text(g.variable,40)||!g.variable||!Object.hasOwn(comparisons,g.op)||!finite(g.value))||r.guardMode!==undefined&&!['all','any'].includes(r.guardMode))throw Error('Check the Only if conditions.');actionsValid(r.actions)}
 const visiting=new Set(),visited=new Set();function visit(id,depth=0){if(visiting.has(id))throw Error('Saved action groups cannot call themselves or form a loop.');if(depth>8)throw Error('Keep saved action groups within eight levels.');if(visited.has(id))return;visiting.add(id);for(const a of groups.find(g=>g.id===id)?.actions||[])if(a.type==='group')visit(a.groupId,depth+1);visiting.delete(id);visited.add(id)}for(const id of groupIds)visit(id);return true}
export function startRules(state,project,context={}){state.ruleRuntime={time:0,timers:new Map(),active:new Set(),tweens:new Map()};dispatchRules(state,project,{type:'start'},context)}
export function dispatchRules(state,project,event,context={}){if(!state)return;state.ruleRuntime??={time:0,timers:new Map(),active:new Set(),tweens:new Map()};for(const r of project.rules||[]){if(r.enabled===false||r.when.type!==event.type)continue;const w=r.when;if(event.type==='key'&&w.code!==event.code||event.type==='mouse'&&w.button!==event.button||['objectclick','touch'].includes(event.type)&&w.objectId!==event.objectId)continue;if(guardsPass(state,r))runActions(state,project,r.actions,context)}}
export function runActions(state,project,actions,context={},depth=0){if(depth>8)return;for(const a of actions||[]){const target=state.objects?.find(o=>o.id===a.targetId);switch(a.type){case'addvariable':case'setvariable':{const value=a.type==='addvariable'?counter(state,a.variable)+a.value:a.value;state.variables??={};state.variables[a.variable]=value;if(a.variable==='Score')state.score=value;if(a.variable==='Health')state.health=Math.max(0,value);break}case'show':case'hide':case'toggle':if(target){target.hidden=a.type==='toggle'?!target.hidden:a.type==='hide';context.onVisibility?.(target,!target.hidden)}break;case'move':if(target){const from=Number(target[a.axis])||0,to=from+a.value,key=target.id+':'+a.axis;state.ruleRuntime?.tweens.delete(key);if(a.duration>0)state.ruleRuntime?.tweens.set(key,{targetId:target.id,axis:a.axis,from,to,duration:a.duration,elapsed:0});else{target[a.axis]=to;context.onTransform?.(target)}}break;case'sound':context.onSound?.(a.soundId,{loop:!!a.loop});break;case'stopsound':context.onStopSound?.(a.soundId);break;case'setgravity':state.gravity=a.value;context.onGravity?.(a.value);break;case'jump':context.onJump?.();break;case'slide':context.onSlide?.();break;case'tag':context.onTag?.();break;case'checkpoint':context.onCheckpoint?.();break;case'finish':state.completed=true;context.onFinish?.();break;case'group':runActions(state,project,project.actionGroups?.find(g=>g.id===a.groupId)?.actions,context,depth+1);break}}}
export function stepRules(state,project,dt,context={}){if(!state.ruleRuntime)startRules(state,project,context);const memory=state.ruleRuntime;memory.time+=Math.max(0,Math.min(dt,.25));for(const[key,t]of memory.tweens){const target=state.objects?.find(o=>o.id===t.targetId);if(!target){memory.tweens.delete(key);continue}t.elapsed=Math.min(t.duration,t.elapsed+dt);target[t.axis]=t.from+(t.to-t.from)*(t.elapsed/t.duration);context.onTransform?.(target);if(t.elapsed>=t.duration)memory.tweens.delete(key)}for(const r of project.rules||[]){if(r.enabled===false)continue;const w=r.when;if(w.type==='timer'){const count=Math.floor((memory.time+1e-9)/w.seconds),previous=memory.timers.get(r.id)||0;if(count>previous){memory.timers.set(r.id,count);if((w.repeat||previous===0)&&guardsPass(state,r))runActions(state,project,r.actions,context)}}else if(['variable','touch'].includes(w.type)){const active=(w.type==='variable'?compare(counter(state,w.variable),w.op,w.value):context.touching?.has(w.objectId)===true)&&guardsPass(state,r);if(active&&!memory.active.has(r.id)){memory.active.add(r.id);runActions(state,project,r.actions,context)}else if(!active)memory.active.delete(r.id)}}}
export function ruleSummary(rule,project){const w=rule.when;const object=id=>project.objects?.find(o=>o.id===id)?.name||'object';let when=w.type==='timer'?`After ${w.seconds}s${w.repeat?' · repeating':''}`:w.type==='key'?`Press ${w.code.replace(/^Key/,'')}`:w.type==='mouse'?`${w.button===2?'Right':w.button===1?'Middle':'Left'} click`:w.type==='objectclick'?`Click ${object(w.objectId)}`:w.type==='touch'?`Touch ${object(w.objectId)}`:w.type==='variable'?`${w.variable} ${comparisons[w.op]} ${w.value}`:'Game starts';const first=rule.actions?.[0],what=first?first.type==='group'?project.actionGroups?.find(g=>g.id===first.groupId)?.name||'Saved actions':actionTypes[first.type]:'Choose action';return`${when} → ${what}${rule.actions?.length>1?` + ${rule.actions.length-1}`:''}`}

export function ruleIssues(rule,project){const issues=[];if(['touch','objectclick'].includes(rule.when?.type)&&!project.objects.some(o=>o.id===rule.when.objectId))issues.push('The trigger object was removed.');for(const action of rule.actions||[]){if(['show','hide','toggle','move'].includes(action.type)&&!project.objects.some(o=>o.id===action.targetId))issues.push('An action target was removed.');if(action.type==='sound'&&!project.sounds?.some(s=>s.id===action.soundId))issues.push('A sound was removed.');if(action.type==='group'&&!project.actionGroups?.some(g=>g.id===action.groupId))issues.push('A saved action group was removed.')}return issues}
